mapper.select:
SELECT SQ.SEQNO,SQ.DEALDATE,SQ.QUOTEID,SQ.NBQUOTEID,SQ.TRADESTATUS,SQ.SENDSTATUS,QSI.ERRORMESSAGE,PP.PORTFOLIO_ID,PP.PORTFOLIO_NAME,
IMI.YWQC,IMI.JYCYQC,SQ.COUNTERTRADER,SQ.PS,SQ.RATE,SQ.DEALAMT,SQ.ZZDAMT,SQ.SQSAMT,SQ.VSETTLEDATE,SQ.TERM,SQ.SETTLETYPE,DL.ITEM_VALUE SETTLESPEED,SQ.TRUSTID,SQ.HOMEROLE,SQ.CREATEDTIME
FROM FX_SECREPO_QUOTE SQ
LEFT JOIN FX_QUOTE_SEND_INFO QSI ON SQ.NBQUOTEID = QSI.NBQUOTEID
LEFT JOIN PTL_PORTFOLIO PP ON SQ.ACCOUNTID = PP.PORTFOLIO_ID
LEFT JOIN FX_IMIX_MEM_INFO IMI ON IMI.JYCYID = SQ.JYCYID
LEFT JOIN SYS_DATADICT_LIST DL ON SQ.SETTLESPEED = DL.ITEM_CODE AND DL.DICT_CODE = #{ACCOUNTSPEED}
WHERE 1=1
 and SQ.QUOTEID = #{quoteid}
 and SQ.TRUSTID = #{trustid}
 and SQ.NBQUOTEID = #{nbquoteid}
 and SQ.QUOTEID = #{portfolioId}
 and SQ.PS = #{ps}
 and SQ.DEALDATE = #{dealdate}
 and SQ.TRADESTATUS = #{tradestatus}
 and SQ.SENDSTATUS = #{sendstatus}

SELECT FP.FINPROD_ABBR,CDATE,PSV.PORTFOLIO_ID ,PSV.FINPROD_ID,SHARE_AMT,DSC_COST_AMT,MBVI.NETPRICE,
MCI.CUSTOMER_NAME TRUSTEE,FP.MDATE
FROM PTL_SEC_VALUTION PSV
LEFT JOIN FIN_PRODUCT FP ON PSV.FINPROD_ID = FP.FINPROD_ID
LEFT JOIN FIN_PRODUCT_TYPE FPT ON FP.FINPROD_ID = FPT.FINPROD_ID
LEFT JOIN MST_BOND_VALUATION_INFO MBVI ON FP.FINPROD_MARKET_ID = MBVI.SEC_ID AND MBVI.VALUE_DATE = PSV.CDATE
LEFT JOIN MST_CUSTOMER_INFO MCI ON FP.TRUSTEE_ID = MCI.CUSTOMER_ID AND MCI.IS_TRUSTER = 'Y'
WHERE PSV.PORTFOLIO_ID = #{portfolioId} AND PSV.CDATE = #{cdate}
AND PSV.FINPROD_ID = #{finprodId}  
AND FPT.TYPE_3 = #{type3}  
AND FPT.TYPE_4 = #{type4}  
ORDER BY PSV.CDATE DESC

SELECT ED.TRADER,EE.ENTRUST_ID,ED.REC_STATUS,EE.PORTFOLIO_ID,EE.FINPROD_ID,PP.PORTFOLIO_NAME,FP.FINPROD_NAME,FP.FINPROD_MARKET_ID,EE.PS,EE.ENTRUST_AMT,EE.ENTRUST_STATUS,EEA.ASSET_TYPE,EEA.BUSI_PS,EE.VDATE,EE.MDATE,EE.ENTRUST_DATE
FROM ETR_DISTRIBUTE ED
LEFT JOIN ETR_ENTRUST EE ON ED.ENTRUST_ID = EE.ENTRUST_ID
LEFT JOIN PTL_PORTFOLIO PP ON EE.PORTFOLIO_ID = PP.PORTFOLIO_ID
LEFT JOIN FIN_PRODUCT FP ON EE.FINPROD_ID = FP.FINPROD_ID
LEFT JOIN ETR_ENTRUST_ADD EEA ON EE.ENTRUST_ID = EEA.ENTRUST_ID
WHERE EEA.ASSET_TYPE = #{ASSET_TYPE}  AND EE.ENTRUST_STATUS = #{ENTRUST_STATUS} AND ED.TRADER = #{TRADER}
AND EE.PORTFOLIO_ID = #{portfolioId}
AND EE.VDATE = #{vdate}
AND EE.MDATE = #{mdate}

select

from FX_SECREPO_QUOTE_HIST
where nbquoteid = #{nbquoteid,jdbcType=VARCHAR}
AND CREATEDTIME = (SELECT MAX(CREATEDTIME) CREATEDTIME
FROM SA_SECREPO_QUOTE_HIST
WHERE NBQUOTEID = #{nbquoteid,jdbcType=VARCHAR}
AND EFFECTFLAG = 'E'
)

SELECT SQ.SEQNO,SQ.DEALDATE,SQ.QUOTEID,SQ.NBQUOTEID,SQ.TRADESTATUS,SQ.SENDSTATUS,SQ.COUNTERTRADER,SQ.PS,SQ.RATE,SQ.DEALAMT,SQ.ZZDAMT,SQ.SQSAMT,SQ.VSETTLEDATE,SQ.TERM,SQ.SETTLETYPE,SQ.TRUSTID,SQ.HOMEROLE,SQ.CREATEDTIME
FROM  FX_SECREPO_QUOTE SQ
WHERE SQ.SEQNO = #{seqno}
